    TEX.smoke = mk(64, (g, s) => { for (let i = 0; i < 14; i++) { const x = R(18, 46), y = R(18, 46), rr = R(8, 20), r = g.createRadialGradient(x, y, 0, x, y, rr); r.addColorStop(0, 'rgba(255,255,255,.35)'); r.addColorStop(1, 'rgba(255,255,255,0)'); g.fillStyle = r; g.fillRect(0, 0, s, s); } });
    TEX.star = mk(64, (g, s) => { g.translate(s / 2, s / 2); g.fillStyle = '#fff'; g.beginPath(); for (let i = 0; i < 10; i++) { const a = i * Math.PI / 5 - Math.PI / 2, r = i % 2 ? 11 : 30; g.lineTo(Math.cos(a) * r, Math.sin(a) * r); } g.fill(); });
    TEX.flare = mk(64, (g, s) => { g.drawImage(TEX.glow, 0, 0); g.fillStyle = 'rgba(255,255,255,.9)'; g.fillRect(s / 2 - 1, 2, 2, s - 4); g.fillRect(2, s / 2 - 1, s - 4, 2); });
    TEX.ring = mk(64, (g, s) => { g.strokeStyle = '#fff'; g.lineWidth = 5; g.beginPath(); g.arc(s / 2, s / 2, 26, 0, TAU); g.stroke(); });
    TEX.bubble = mk(64, (g, s) => { g.strokeStyle = 'rgba(255,255,255,.9)'; g.lineWidth = 3; g.beginPath(); g.arc(32, 32, 27, 0, TAU); g.stroke(); g.fillStyle = 'rgba(255,255,255,.18)'; g.fill(); g.fillStyle = 'rgba(255,255,255,.9)'; g.beginPath(); g.ellipse(22, 20, 6, 4, -0.6, 0, TAU); g.fill(); });
    TEX.drop = mk(64, (g) => { g.fillStyle = '#fff'; g.beginPath(); g.moveTo(32, 6); g.bezierCurveTo(52, 34, 46, 58, 32, 58); g.bezierCurveTo(18, 58, 12, 34, 32, 6); g.fill(); });
    TEX.leaf = mk(64, (g) => { g.fillStyle = '#fff'; g.beginPath(); g.moveTo(8, 32); g.quadraticCurveTo(32, 2, 56, 32); g.quadraticCurveTo(32, 62, 8, 32); g.fill(); g.strokeStyle = 'rgba(0,0,0,.25)'; g.lineWidth = 2; g.beginPath(); g.moveTo(8, 32); g.lineTo(56, 32); g.stroke(); });
    TEX.snow = mk(64, (g, s) => { g.translate(32, 32); g.strokeStyle = '#fff'; g.lineWidth = 3; g.lineCap = 'round'; for (let i = 0; i < 6; i++) { g.rotate(Math.PI / 3); g.beginPath(); g.moveTo(0, 0); g.lineTo(0, 26); g.moveTo(0, 14); g.lineTo(7, 20); g.moveTo(0, 14); g.lineTo(-7, 20); g.stroke(); } });
    TEX.heart = mk(64, (g) => { g.fillStyle = '#fff'; g.beginPath(); g.moveTo(32, 54); g.bezierCurveTo(4, 34, 10, 8, 32, 20); g.bezierCurveTo(54, 8, 60, 34, 32, 54); g.fill(); });
    TEX.plus = mk(64, (g) => { g.fillStyle = '#fff'; g.fillRect(24, 8, 16, 48); g.fillRect(8, 24, 48, 16); });
    TEX.coin = mk(64, (g) => { const r = g.createLinearGradient(0, 0, 64, 64); r.addColorStop(0, '#fff3a0'); r.addColorStop(.5, '#ffc61a'); r.addColorStop(1, '#c97a00'); g.fillStyle = r; g.beginPath(); g.arc(32, 32, 28, 0, TAU); g.fill(); g.strokeStyle = '#a45f00'; g.lineWidth = 4; g.stroke(); g.fillStyle = 'rgba(255,255,255,.75)'; g.font = 'bold 30px sans-serif'; g.textAlign = 'center'; g.textBaseline = 'middle'; g.fillText('C', 32, 34); });
