    TEX.spark = mk(64, (g) => { const r = g.createLinearGradient(0, 32, 64, 32); r.addColorStop(0, 'rgba(255,255,255,0)'); r.addColorStop(.7, 'rgba(255,255,255,1)'); r.addColorStop(1, 'rgba(255,255,255,0)'); g.fillStyle = r; g.fillRect(0, 28, 64, 8); });
