    emit(o) { if (this.p.length >= this.max) this.p.shift(); const p = Object.assign({ x: 0, y: 0, vx: 0, vy: 0, ax: 0, ay: 0, drag: 0, life: 1, t: 0, s0: 8, s1: 0, a0: 1, a1: 0, rot: 0, spin: 0, tex: 'glow', color: '#fff', add: true, stretch: 0, wob: 0 }, o); this.p.push(p); return p; }
