        if (p.text) { g.save(); g.translate(p.x, p.y); const pop = p.pop ? 1 + 0.6 * Math.max(0, 1 - u * 6) : 1; g.scale(pop, pop); g.font = `900 ${s}px system-ui,sans-serif`; g.textAlign = 'center'; g.textBaseline = 'middle'; g.lineWidth = Math.max(3, s / 7); g.strokeStyle = p.stroke || 'rgba(0,0,0,.65)'; g.strokeText(p.text, 0, 0); g.fillStyle = p.color; g.fillText(p.text, 0, 0); g.restore(); continue; }
