  def('confetti_rain', 'confetti from the top of the screen', (fx) => fx.burst(140, 0, 0, () => ({ x: R(0, fx.w), y: R(-200, -10), vy: R(60, 160), vx: R(-30, 30), life: R(3, 4.5), s0: R(7, 12), s1: 8, a1: .8, tex: 'square', color: pick(RAINBOW), add: false, spin: R(-10, 10), rot: 1, wob: 80 })));
