  def('fireball', 'fireball trail burst', (fx, x, y) => { fx.burst(30, x, y, () => Object.assign(radial(20, 200), { life: R(.3, .6), s0: R(18, 30), s1: 0, tex: 'glow', color: pick(['#fff3c0', '#ffa030', '#ff4010']), drag: 2 })); fx.screenShake(4, .2); });
  def('sparks', 'metal sparks', (fx, x, y) => fx.burst(30, x, y, () => ({ vx: R(-260, 260), vy: R(-340, -40), ay: 900, life: R(.3, .7), s0: R(6, 10), s1: 2, tex: 'spark', stretch: .05, color: pick(['#fff7d0', '#ffd060', '#ff9a20']) })));
