  def('electricity', 'electric arcs', (fx, x, y) => { for (let k = 0; k < 4; k++) fx.addFX({ life: .45, seed: Math.random(), draw(g, f) { const u = f.t / f.life; g.globalCompositeOperation = 'lighter'; g.strokeStyle = '#9fe8ff'; g.shadowColor = '#3ad1ff'; g.shadowBlur = 12; g.lineWidth = 2.5 * (1 - u) + .5; g.globalAlpha = Math.random() < .2 ? .3 : 1 - u; g.beginPath(); const a = f.seed * TAU + k, L = 110; let px = x, py = y; g.moveTo(px, py); for (let i = 1; i <= 8; i++) { px = x + Math.cos(a) * L * i / 8 + R(-14, 14); py = y + Math.sin(a) * L * i / 8 + R(-14, 14); g.lineTo(px, py); } g.stroke(); g.shadowBlur = 0; g.globalAlpha = 1; g.globalCompositeOperation = 'source-over'; } }); fx.burst(12, x, y, () => Object.assign(radial(60, 220), { life: .3, s0: 8, s1: 0, tex: 'glow', color: '#9fe8ff' })); fx.hitFlash('#bfefff', .1, .25); });
  def('lightning_strike', 'lightning bolt from the sky', (fx, x, y) => { fx.addFX({ life: .5, draw(g, f) { const u = f.t / f.life; g.globalCompositeOperation = 'lighter'; g.strokeStyle = '#e8f6ff'; g.shadowColor = '#7cc8ff'; g.shadowBlur = 20; g.lineWidth = 5 * (1 - u) + 1; g.globalAlpha = (Math.sin(f.t * 60) > -.3 ? 1 : .3) * (1 - u); g.beginPath(); let px = x + R(-30, 30), py = 0; g.moveTo(px, py); const n = 12; for (let i = 1; i <= n; i++) { px = lerp(px, x, .35) + R(-24, 24); py = y * i / n; g.lineTo(px, py); } g.stroke(); g.shadowBlur = 0; g.globalAlpha = 1; g.globalCompositeOperation = 'source-over'; } }); fx.hitFlash('#dff2ff', .25, .6); fx.screenShake(10, .3); ringFX(fx, x, y, { color: '#9fd8ff', r1: 100 }); });
