  def('speed_streaks', 'horizontal speed streaks', (fx) => loopFX(fx, 1.2, 60, () => fx.emit({ x: fx.w + 20, y: R(0, fx.h), vx: -R(1400, 2200), life: .6, s0: R(6, 12), s1: 6, a0: .5, tex: 'spark', stretch: .03, color: '#ffffff' })));
  def('nitro_flame', 'nitro exhaust flame (aims left)', (fx, x, y) => loopFX(fx, 1.5, 140, () => fx.emit({ x, y: y + R(-4, 4), vx: -R(400, 650), vy: R(-30, 30), drag: 3, life: R(.15, .35), s0: R(16, 26), s1: 2, tex: 'glow', color: pick(['#e0f4ff', '#60a5fa', '#3b82f6', '#a78bfa']) })));
  def('exhaust_backfire', 'exhaust pop', (fx, x, y) => fx.burst(14, x, y, () => ({ vx: -R(120, 320), vy: R(-50, 50), drag: 4, life: R(.15, .3), s0: R(14, 24), s1: 0, tex: 'glow', color: pick(['#fff0b0', '#ff9a30']) })));
  def('tire_smoke', 'tire smoke (drift)', (fx, x, y) => loopFX(fx, 1.8, 45, () => fx.emit({ x: x + R(-6, 6), y: y + R(-4, 4), vx: R(-60, -10), vy: -R(5, 30), drag: 1.2, life: R(1, 2), s0: 14, s1: R(70, 110), a0: .55, tex: 'smoke', color: '#e5e7eb', add: false, fadeIn: true })));
  def('skid_marks_puff', 'quick skid puff', (fx, x, y) => fx.burst(10, x, y, () => ({ vx: R(-80, 80), vy: R(-20, 0), drag: 2, life: .8, s0: 12, s1: 50, a0: .6, tex: 'smoke', color: '#d1d5db', add: false })));
