  def('hit_spark', 'impact hit spark', (fx, x, y) => { fx.burst(10, x, y, () => Object.assign(radial(150, 380), { life: .2, s0: 10, s1: 2, tex: 'spark', stretch: .04, color: '#fff' })); fx.emit({ x, y, life: .12, s0: 50, s1: 70, tex: 'flare', color: '#fff' }); });
  def('coin_burst', 'coins burst out', (fx, x, y) => fountain(fx, x, y, 22, 220, () => ({ ay: 800, life: R(.8, 1.2), s0: R(18, 26), s1: R(16, 22), a1: .8, tex: 'coin', color: '#fff', add: false, spin: R(-6, 6), rot: .01 })));
  def('coin_collect', 'coin collect sparkle', (fx, x, y) => { fx.emit({ x, y, vy: -120, drag: 3, life: .45, s0: 26, s1: 10, tex: 'coin', color: '#fff', add: false }); fx.burst(10, x, y, () => Object.assign(radial(40, 140), { life: .4, s0: 10, s1: 0, tex: 'flare', color: '#ffe680', drag: 3 })); textPop(fx, x, y - 24, '+1', '#ffd23f', 22, .8); });
  def('star_pop', 'star pop', (fx, x, y) => { fx.emit({ x, y, life: .6, s0: 20, s1: 70, a0: 1.2, tex: 'star', color: '#ffd84a' }); fx.burst(12, x, y, () => Object.assign(radial(80, 220), { life: .6, s0: 14, s1: 0, tex: 'star', color: pick(['#fff3a0', '#ffd84a']), spin: R(-6, 6), rot: .1, drag: 3 })); });
  def('star_rating', 'three stars pop in order', (fx, x, y) => [-60, 0, 60].forEach((dx, i) => setTimeout(() => PRESETS.star_pop.fn(fx, x + dx, y - (i === 1 ? 14 : 0)), i * 280)));
  def('trail', 'glowing trail (follows a path for 1.5 s)', (fx, x, y) => loopFX(fx, 1.5, 90, u => { const a = u * TAU * 1.5; fx.emit({ x: x + Math.cos(a) * 80, y: y + Math.sin(a * 2) * 40, life: .5, s0: 18, s1: 0, tex: 'glow', color: pick(['#7dd3fc', '#c084fc']) }); }));
  def('rainbow_trail', 'rainbow trail', (fx, x, y) => loopFX(fx, 1.5, 100, u => fx.emit({ x: x - 120 + u * 240, y: y + Math.sin(u * 12) * 30, life: .7, s0: 16, s1: 0, tex: 'glow', color: RAINBOW[(u * 40 | 0) % 7] })));
  def('fireworks', 'firework show (3 rockets)', (fx, x, y) => { for (let k = 0; k < 3; k++) setTimeout(() => { const tx = x + R(-120, 120), ty = y - R(80, 200), col = pick(RAINBOW); const r = fx.emit({ x: tx, y: fx.h, vy: -(fx.h - ty) * 1.9, ay: (fx.h - ty) * 1.8, life: 1, s0: 8, s1: 6, tex: 'glow', color: '#fff3c0' }); setTimeout(() => { fx.burst(60, tx, ty, () => Object.assign(radial(60, 260), { life: R(.9, 1.5), s0: 9, s1: 0, ay: 120, drag: 1.5, tex: 'glow', color: Math.random() < .2 ? '#fff' : col })); ringFX(fx, tx, ty, { color: col, r1: 70, life: .4, width: 4 }); }, 1000 * .55); }, k * 380); });
  def('level_up_glow', 'level-up column glow', (fx, x, y) => { fx.addFX({ life: 1.2, under: true, draw(g, f) { const u = f.t / f.life, a = Math.sin(u * Math.PI); const gr = g.createLinearGradient(0, y - 200, 0, y + 40); gr.addColorStop(0, 'rgba(255,230,120,0)'); gr.addColorStop(1, `rgba(255,230,120,${.55 * a})`); g.fillStyle = gr; g.fillRect(x - 70, y - 200, 140, 240); } }); loopFX(fx, 1, 50, () => fx.emit({ x: x + R(-60, 60), y: y + 20, vy: -R(120, 260), life: .9, s0: 10, s1: 0, tex: 'flare', color: pick(['#fff3a0', '#ffd84a', '#fff']) })); textPop(fx, x, y - 120, 'LEVEL UP!', '#ffe14a', 40, 1.4, -30); });
  def('shockwave', 'shockwave ring', (fx, x, y) => { ringFX(fx, x, y, { color: '#ffffff', r1: 180, life: .55, width: 14 }); ringFX(fx, x, y, { color: '#7dd3fc', r1: 140, life: .45, width: 6 }); fx.screenShake(6, .2); });
  def('heal', 'healing pluses rise', (fx, x, y) => { fx.burst(16, x, y, () => ({ x: x + R(-40, 40), y: y + R(-10, 30), vy: -R(50, 110), life: R(.8, 1.3), s0: R(12, 20), s1: 6, tex: 'plus', color: pick(['#4ade80', '#a7f3d0']) })); fx.emit({ x, y, life: .8, s0: 60, s1: 140, a0: .5, tex: 'glow', color: '#4ade80' }); textPop(fx, x, y - 50, '+25', '#4ade80', 28); });
  def('shield', 'shield bubble (2 s)', (fx, x, y) => { fx.addFX({ life: 2, draw(g, f) { const u = f.t / f.life, a = Math.min(1, f.t * 5) * (u > .85 ? (1 - u) / .15 : 1), r = 60 + 3 * Math.sin(f.t * 10); g.globalCompositeOperation = 'lighter'; const gr = g.createRadialGradient(x, y, r * .6, x, y, r); gr.addColorStop(0, 'rgba(90,200,255,0)'); gr.addColorStop(1, `rgba(90,200,255,${.5 * a})`); g.fillStyle = gr; g.beginPath(); g.arc(x, y, r, 0, TAU); g.fill(); g.strokeStyle = `rgba(200,240,255,${.9 * a})`; g.lineWidth = 2; g.beginPath(); g.arc(x, y, r, f.t * 3, f.t * 3 + 1.2); g.stroke(); g.beginPath(); g.arc(x, y, r, f.t * 3 + 3, f.t * 3 + 4.2); g.stroke(); g.globalCompositeOperation = 'source-over'; } }); });
  def('shield_break', 'shield shatters', (fx, x, y) => { fx.burst(30, x, y, () => Object.assign(radial(120, 300), { life: .6, s0: R(6, 12), s1: 2, ay: 400, tex: 'square', color: '#9fe2ff', spin: R(-10, 10), rot: 1, drag: 1 })); ringFX(fx, x, y, { color: '#9fe2ff', r0: 60, r1: 110, life: .3 }); fx.hitFlash('#bfeaff', .1, .3); });
  def('portal', 'swirling portal (2.5 s)', (fx, x, y) => { fx.addFX({ life: 2.5, under: true, draw(g, f) { const u = f.t / f.life, a = Math.min(1, f.t * 3) * (u > .85 ? (1 - u) / .15 : 1); g.save(); g.translate(x, y); g.scale(1, 1.4); for (let i = 0; i < 4; i++) { g.rotate(f.t * (2 + i)); g.strokeStyle = `hsla(${270 - i * 25},90%,${60 + i * 8}%,${a * .8})`; g.lineWidth = 6 - i; g.beginPath(); g.arc(0, 0, 50 - i * 9, 0, 4.5); g.stroke(); } const gr = g.createRadialGradient(0, 0, 0, 0, 0, 50); gr.addColorStop(0, `rgba(255,255,255,${a * .9})`); gr.addColorStop(.4, `rgba(160,90,255,${a * .5})`); gr.addColorStop(1, 'rgba(80,20,160,0)'); g.fillStyle = gr; g.beginPath(); g.arc(0, 0, 50, 0, TAU); g.fill(); g.restore(); } }); loopFX(fx, 2.3, 40, () => { const a = R(0, TAU), r = R(80, 120); fx.emit({ x: x + Math.cos(a) * r, y: y + Math.sin(a) * r * 1.4, vx: -Math.cos(a) * r * 1.6, vy: -Math.sin(a) * r * 2.2, life: .6, s0: 8, s1: 2, tex: 'glow', color: pick(['#c4b5fd', '#f0abfc']) }); }); });
  def('teleport', 'teleport beam', (fx, x, y) => { fx.addFX({ life: .7, draw(g, f) { const u = f.t / f.life, w = 40 * Math.sin(u * Math.PI); g.globalCompositeOperation = 'lighter'; const gr = g.createLinearGradient(x - w, 0, x + w, 0); gr.addColorStop(0, 'rgba(120,200,255,0)'); gr.addColorStop(.5, 'rgba(220,245,255,.9)'); gr.addColorStop(1, 'rgba(120,200,255,0)'); g.fillStyle = gr; g.fillRect(x - w, 0, w * 2, y + 30); g.globalCompositeOperation = 'source-over'; } }); fx.burst(24, x, y, () => ({ x: x + R(-20, 20), y: y + R(-40, 20), vy: -R(100, 300), life: .7, s0: 8, s1: 0, tex: 'glow', color: '#bfe8ff' })); });
  def('snow', 'snowfall (5 s)', (fx) => loopFX(fx, 5, 40, () => fx.emit({ x: R(-20, fx.w + 20), y: -20, vy: R(40, 90), vx: R(-20, 20), life: R(5, 8), s0: R(8, 18), s1: R(8, 18), a0: .9, a1: .7, tex: 'snow', color: '#fff', add: false, spin: R(-1, 1), rot: .1, wob: 30 })));
