  def('leaves', 'falling leaves (5 s)', (fx) => loopFX(fx, 5, 10, () => fx.emit({ x: R(0, fx.w), y: -20, vy: R(40, 80), vx: R(10, 50), life: R(6, 9), s0: R(16, 26), s1: R(16, 26), a1: .8, tex: 'leaf', color: pick(['#e0782b', '#d4a017', '#b5401c', '#8fae3c']), add: false, spin: R(-2, 2), rot: 1, wob: 70 })));
