  def('magic_sparkles', 'magic spell sparkles', (fx, x, y) => { loopFX(fx, 1, 70, u => { const a = u * TAU * 3, r = 70 * (1 - u); fx.emit({ x: x + Math.cos(a) * r, y: y + Math.sin(a) * r, vy: -30, life: .7, s0: 14, s1: 0, tex: 'star', color: pick(['#e9d5ff', '#c084fc', '#f0abfc']), spin: 4, rot: .1 }); }); setTimeout(() => PRESETS.sparkle_burst.fn(fx, x, y), 1000); });
  def('magic_circle', 'rotating magic circle', (fx, x, y) => fx.addFX({ life: 2, under: true, draw(g, f) { const u = f.t / f.life, a = Math.min(1, f.t * 3) * (u > .8 ? (1 - u) / .2 : 1); g.save(); g.translate(x, y); g.scale(1, .45); g.rotate(f.t * 1.5); g.strokeStyle = `rgba(200,150,255,${a})`; g.shadowColor = '#c084fc'; g.shadowBlur = 14; g.lineWidth = 3; g.beginPath(); g.arc(0, 0, 90, 0, TAU); g.stroke(); g.beginPath(); g.arc(0, 0, 70, 0, TAU); g.stroke(); for (let i = 0; i < 8; i++) { const t = i * TAU / 8; g.beginPath(); g.arc(Math.cos(t) * 80, Math.sin(t) * 80, 7, 0, TAU); g.stroke(); } g.strokeRect(-45, -45, 90, 90); g.rotate(Math.PI / 4); g.strokeRect(-45, -45, 90, 90); g.restore(); } }));
  def('dark_magic', 'dark purple burst', (fx, x, y) => { fx.burst(30, x, y, () => Object.assign(radial(30, 160), { life: R(.6, 1.1), s0: R(20, 40), s1: 0, tex: 'smoke', color: pick(['#4c1d95', '#7c3aed', '#1e1b4b']), add: false, drag: 2, a0: .9 })); fx.burst(14, x, y, () => Object.assign(radial(40, 200), { life: .5, s0: 10, s1: 0, tex: 'glow', color: '#c084fc' })); });
  def('ice_shatter', 'ice crystals shatter', (fx, x, y) => fx.burst(26, x, y, () => Object.assign(radial(100, 320), { ay: 500, life: R(.5, .9), s0: R(8, 16), s1: 2, tex: 'star', color: pick(['#e0f2fe', '#7dd3fc', '#ffffff']), spin: R(-8, 8), rot: 1, drag: 1.5 })));
