  def('power_up', 'power-up aura burst', (fx, x, y) => { fx.burst(30, x, y, i => { const a = i / 30 * TAU; return { x: x + Math.cos(a) * 90, y: y + Math.sin(a) * 90, vx: -Math.cos(a) * 200, vy: -Math.sin(a) * 200, life: .45, s0: 10, s1: 4, tex: 'glow', color: '#fde047' }; }); setTimeout(() => { ringFX(fx, x, y, { color: '#fde047', r1: 120 }); fx.emit({ x, y, life: .5, s0: 40, s1: 160, a0: .7, tex: 'glow', color: '#fde047' }); }, 450); });
  def('unlock_burst', 'unlock rays + sparkles', (fx, x, y) => { fx.addFX({ life: 1.3, under: true, draw(g, f) { const u = f.t / f.life, a = Math.sin(u * Math.PI) * .5; g.save(); g.translate(x, y); g.rotate(f.t * .6); g.fillStyle = `rgba(255,230,140,${a})`; for (let i = 0; i < 12; i++) { g.rotate(TAU / 12); g.beginPath(); g.moveTo(0, 0); g.lineTo(-14, -220); g.lineTo(14, -220); g.fill(); } g.restore(); } }); PRESETS.sparkle_burst.fn(fx, x, y); });
