  def('jump_puff', 'jump puff', (fx, x, y) => fx.burst(8, x, y, i => ({ vx: (i - 3.5) * 30, vy: R(-20, 10), drag: 4, life: .4, s0: 10, s1: 24, a0: .8, tex: 'smoke', color: '#ffffff', add: false })));
