  def('charge_up', 'charging energy (1.2 s)', (fx, x, y) => { loopFX(fx, 1.2, 60, u => { const a = R(0, TAU), r = 110 - u * 50; fx.emit({ x: x + Math.cos(a) * r, y: y + Math.sin(a) * r, vx: -Math.cos(a) * r * 2.5, vy: -Math.sin(a) * r * 2.5, life: .4, s0: 6 + u * 8, s1: 2, tex: 'glow', color: pick(['#a5f3fc', '#ffffff']) }); }); setTimeout(() => PRESETS.shockwave.fn(fx, x, y), 1200); });
  def('laser_beam', 'laser beam across screen', (fx, x, y) => { fx.addFX({ life: .5, draw(g, f) { const u = f.t / f.life, w = 18 * Math.sin(u * Math.PI); g.globalCompositeOperation = 'lighter'; const gr = g.createLinearGradient(0, y - w, 0, y + w); gr.addColorStop(0, 'rgba(255,60,120,0)'); gr.addColorStop(.5, 'rgba(255,230,240,1)'); gr.addColorStop(1, 'rgba(255,60,120,0)'); g.fillStyle = gr; g.fillRect(x, y - w, fx.w - x, w * 2); g.globalCompositeOperation = 'source-over'; } }); fx.burst(14, x, y, () => Object.assign(radial(60, 200), { life: .3, s0: 10, s1: 0, tex: 'glow', color: '#ff7aa8' })); });
